const config = $('Set: config').first().json;
const resp = $input.first().json;

const currentRate = resp.rates && resp.rates[config.targetCurrency];
if (typeof currentRate !== 'number') {
  throw new Error('Check for significant move: could not find a rate for ' + config.targetCurrency + ' in the API response.');
}

const staticData = $getWorkflowStaticData('global');
const previousRate = staticData.lastRate;
const isFirstRun = typeof previousRate !== 'number';

let changePercent = 0;
if (!isFirstRun) {
  changePercent = ((currentRate - previousRate) / previousRate) * 100;
}

const significant = isFirstRun || Math.abs(changePercent) >= config.thresholdPercent;

staticData.lastRate = currentRate;
staticData.lastCheckedAt = resp.date;

return [{
  json: {
    significant,
    isFirstRun,
    baseCurrency: config.baseCurrency,
    targetCurrency: config.targetCurrency,
    currentRate,
    previousRate: previousRate || null,
    changePercent: Number(changePercent.toFixed(3)),
    rateDate: resp.date,
    slackWebhookUrl: config.slackWebhookUrl
  }
}];

const d = $input.first().json;

const systemPrompt = 'You write short, neutral commentary on currency exchange rate movements. State only the facts given to you (the rate, the percentage change, the date). Do not predict future rates, do not give investment or trading advice, and do not invent causes for the movement unless they were provided to you.';

const movementText = d.isFirstRun
  ? `This is the first recorded rate: 1 ${d.baseCurrency} = ${d.currentRate} ${d.targetCurrency} (as of ${d.rateDate}).`
  : `${d.baseCurrency}/${d.targetCurrency} moved from ${d.previousRate} to ${d.currentRate} (${d.changePercent > 0 ? '+' : ''}${d.changePercent}%) as of ${d.rateDate}.`;

const userPrompt = `Write a 2-3 sentence factual note about this exchange rate update for a team that tracks currency risk:\n\n${movementText}`;

return [{ json: { systemPrompt, userPrompt, slackWebhookUrl: d.slackWebhookUrl, baseCurrency: d.baseCurrency, targetCurrency: d.targetCurrency } }];

const resp = $input.first().json;
const promptCtx = $('Build Claude prompt').first().json;

const textBlock = (resp.content || []).find((b) => b.type === 'text');
const commentary = (textBlock && textBlock.text) || '(no commentary text returned)';

return [{
  json: {
    slackWebhookUrl: promptCtx.slackWebhookUrl,
    slackRequestBody: { text: `:currency_exchange: *${promptCtx.baseCurrency}/${promptCtx.targetCurrency} rate update*\n${commentary}` }
  }
}];
